CREATE TABLE admins (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, admin_id INT NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE);
CREATE TABLE cms_records (id INT PRIMARY KEY AUTO_INCREMENT, kind ENUM('entity','property','page','space','settings','payment') NOT NULL, slug VARCHAR(190) NOT NULL, title VARCHAR(255) NOT NULL, entity_id INT NULL, property_id INT NULL, payload JSON NOT NULL, published_payload JSON NULL, published_slug VARCHAR(190) NULL, published_title VARCHAR(255) NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY(kind,slug), UNIQUE KEY(kind,published_slug), FOREIGN KEY(entity_id) REFERENCES cms_records(id), FOREIGN KEY(property_id) REFERENCES cms_records(id));
CREATE TABLE media (id INT PRIMARY KEY AUTO_INCREMENT, filename VARCHAR(255) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime VARCHAR(80) NOT NULL, alt VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id INT PRIMARY KEY AUTO_INCREMENT, admin_id INT NOT NULL, action VARCHAR(80) NOT NULL, record_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(admin_id) REFERENCES admins(id));
